import { Mesh, PlaneGeometry, Object3D, Vector3, Euler } from 'three/webgpu';
import { MeshBasicNodeMaterial } from 'three/tsl';
import { gsap } from 'gsap';
import '@/primitives';
import '@/text';

/**
 * @typedef {Object} NodeConfig
 * @property {{ imageUrl?: string }} assets
 * @property {[number, number, number]?} position
 * @property {[number, number, number]?} rotation
 * @property {[number, number, number]?} scale
 * @property {Array<{ name: string, params: any }>} [cinematicPrimitives]
 */

/**
 * @typedef {Object} NodeContext
 * @property {(url: string) => any} textureLoader
 * @property {{ [key: string]: (target: Object3D, params: any) => void }} primitives
 */

/**
 * Creates a textured plane node.
 * @param {NodeConfig} config
 * @param {NodeContext} ctx
 * @returns {THREE.Object3D}
 */
export default function createNode(config, ctx) {
  const { assets = {}, position = [0, 0, 0], rotation = [0, 0, 0], scale = [1, 1, 1] } = config;

  // Geometry (unit plane)
  const geometry = new PlaneGeometry(1, 1);

  // Load texture (synchronous via cached loader)
  const texture = assets.imageUrl ? ctx.textureLoader(assets.imageUrl) : null;

  // Material
  const material = new MeshBasicNodeMaterial({
    map: texture ?? undefined,
    transparent: true,
    depthWrite: true,
  });

  // Mesh
  const plane = new Mesh(geometry, material);
  plane.position.set(...position);
  plane.rotation.set(...rotation);
  plane.scale.set(...scale);

  // Apply cinematic primitives if any
  if (Array.isArray(config.cinematicPrimitives)) {
    for (const prim of config.cinematicPrimitives) {
      const fn = ctx.primitives[prim.name];
      if (typeof fn === 'function') {
        fn(plane, prim.params);
      }
    }
  }

  // Handlers placeholder (no interactions defined)
  plane.userData.handlers = {};

  // GSAP timelines tracking
  const timelines = [];

  // Cleanup routine
  plane.userData.cleanup = () => {
    // Kill GSAP timelines
    for (const tl of timelines) {
      tl.kill();
    }
    // Dispose resources
    geometry.dispose();
    material.dispose();
    if (texture && typeof texture.dispose === 'function') {
      texture.dispose();
    }
  };

  return plane;
}
